      { ar: 'فتحة المزمار', en: 'The glottis' },
      { ar: 'الطيتان الدهليزيتان', en: 'The vestibular folds' },
      { ar: 'الغضروفان الطرجهاليان', en: 'The arytenoid cartilages' }
